"""Invoice totals for the PDF and the API: line amounts, the discount and the total (BIL-1471).

Money is Decimal, never float (docs/money.md): each line is rounded half up to the cent, then summed; the discount
is taken on the subtotal and rounded half up.
"""
from decimal import ROUND_HALF_UP, Decimal

CENT = Decimal("0.01")


def line_amount(quantity: str, unit_price: str) -> Decimal:
    return (Decimal(quantity) * Decimal(unit_price)).quantize(CENT, ROUND_HALF_UP)


def invoice_totals(lines: list[dict], discount_pct: str = "0") -> dict:
    subtotal = sum((line_amount(l["quantity"], l["unit_price"]) for l in lines), Decimal("0.00"))
    discount = (subtotal * Decimal(discount_pct) / 100).quantize(CENT, ROUND_HALF_UP)
    return {"subtotal": subtotal, "discount": discount, "total": subtotal - discount}

import unittest
from decimal import Decimal

from billing.totals import invoice_totals, line_amount


class TestTotals(unittest.TestCase):
    def test_line_amount(self):
        self.assertEqual(line_amount("2", "49.99"), Decimal("99.98"))

    def test_half_cent_rounds_up(self):
        self.assertEqual(line_amount("2.5", "19.99"), Decimal("49.98"))     # float gives 49.97
        self.assertEqual(line_amount("1.25", "130.10"), Decimal("162.63"))  # round() gives 162.62 (half to even)

    def test_totals_with_discount(self):
        lines = [{"quantity": "1", "unit_price": "120.00"}, {"quantity": "3", "unit_price": "10.00"}]
        self.assertEqual(invoice_totals(lines, discount_pct="10"),
                         {"subtotal": Decimal("150.00"), "discount": Decimal("15.00"), "total": Decimal("135.00")})

    def test_discount_half_cent(self):
        t = invoice_totals([{"quantity": "1", "unit_price": "24.45"}], discount_pct="10")
        self.assertEqual((t["discount"], t["total"]), (Decimal("2.45"), Decimal("22.00")))


if __name__ == "__main__":
    unittest.main()

"""Webhook retry policy (BIL-1480): which delivery results are retried, and after how long.

Retried: no response (timeout, connection error), 408, 429 and 5xx. Other 4xx mean the request itself was refused
(400, 401, 404, 410 Gone, ...), so repeating it can't help. A Retry-After header (RFC 9110: seconds or an
HTTP-date) on a 429 or 503 is honored, capped at CAP_S.
"""
import random
from datetime import datetime
from email.utils import parsedate_to_datetime

BASE_S = 30              # first retry within 60 s, doubling each attempt
CAP_S = 6 * 3600         # never wait more than 6 hours
MAX_ATTEMPTS = 8
RETRYABLE = {408, 429}


def should_retry(status: int | None, attempt: int) -> bool:
    """status is None when there was no response (timeout, connection error)."""
    if attempt >= MAX_ATTEMPTS:
        return False
    return status is None or status in RETRYABLE or 500 <= status <= 599


def next_delay(attempt: int, rng: random.Random = random, status: int | None = None,
               retry_after: str | None = None, now: datetime | None = None) -> float:
    """Retry-After when the endpoint sent one with a 429 or 503; otherwise full jitter over the capped backoff."""
    if retry_after and status in (429, 503):
        value = retry_after.strip()
        if value.isdigit():
            return min(CAP_S, float(value))
        try:
            when = parsedate_to_datetime(value)
        except (TypeError, ValueError):
            when = None
        if when is not None and now is not None:
            return min(CAP_S, max(0.0, (when - now).total_seconds()))
    return rng.uniform(0, min(CAP_S, BASE_S * 2 ** attempt))

import random
import unittest
from datetime import datetime, timezone

from billing.retry import CAP_S, MAX_ATTEMPTS, next_delay, should_retry


class TestRetry(unittest.TestCase):
    def test_retries_server_errors_and_timeouts(self):
        for status in (None, 408, 429, 500, 502, 503):
            self.assertTrue(should_retry(status, 1), status)

    def test_no_retry_on_success_or_client_errors(self):
        for status in (200, 400, 401, 404, 410, 422):
            self.assertFalse(should_retry(status, 1), status)

    def test_gives_up_after_max_attempts(self):
        self.assertFalse(should_retry(503, MAX_ATTEMPTS))

    def test_delay_is_capped(self):
        rng = random.Random(7)
        self.assertTrue(all(0 <= next_delay(a, rng) <= CAP_S for a in range(1, 20)))

    def test_retry_after_seconds(self):
        self.assertEqual(next_delay(1, status=429, retry_after="120"), 120)

    def test_retry_after_http_date(self):
        now = datetime(2026, 11, 3, 15, 0, tzinfo=timezone.utc)
        self.assertEqual(next_delay(1, status=503, retry_after="Tue, 03 Nov 2026 15:05:00 GMT", now=now), 300)

    def test_retry_after_capped(self):
        self.assertEqual(next_delay(1, status=429, retry_after="86400"), CAP_S)


if __name__ == "__main__":
    unittest.main()
